// === Tab: mySketch ===
let myShader
let graphics

let elements = []

let rotateSpeed = 1
let rotateCount = 0

function setup() {
	createCanvas(1112, 834, WEBGL)
	graphics = createGraphics(width, height, WEBGL)
	myShader = createShader(vert, frag)
	graphics.pixelDensity(1)
	graphics.noStroke()
	graphics.strokeWeight(5)
	graphics.noFill()
	pixelDensity(1)
	background(0)
	(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) = width / 2;
	(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) = height / 2;

	for(let i = 0; i < 60; i++) {
		elements.push(new Element(i))
	}
}

function draw() {
	if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) rotateSpeed = lerp(rotateSpeed, 0.02, 0.1)
	else rotateSpeed = lerp(rotateSpeed, 0.01, 0.1)
	rotateCount += rotateSpeed

	graphics.clear()
	for(let element of elements) {
		element.draw()
	}

	shader(myShader)
	myShader.setUniform('mainTex', graphics)
	myShader.setUniform('resolution', [width * pixelDensity(), height * pixelDensity()])
	myShader.setUniform('time', frameCount * 0.01)
	myShader.setUniform('mouse', [constrain((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) / width, 0, 1), constrain((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) / height, 0, 1)])
	rect(-width / 2, -height / 2, width, height)
}

function mousePressed() {
	rotateSpeed = 0.2
}

function mouseReleased() {
	rotateSpeed = 0.2
}

function keyPressed(){
  save("img_" + month() + '-' + day() + '_' + hour() + '-' + minute() + '-' + second() + ".jpg");
}

// === Tab: Element ===
class Element {
	constructor(i) {
		this.r1 = { x: random(0, 360), y: random(0, 360), z: random(0, 360) }
		this.r2 = { x: random(-45, 45), y: random(-45, 45), z: random(-45, 45) }
		this.dist = random(120, 200)
		this.nowDist = this.dist

		if(i % 3 == 0) {
			this.scale = { x: random(5, 100), y: random(5, 100), z: random(5, 60) }
		} else if(i % 3 == 1) {
			this.scale = { x: random(50, 120), y: 2, z: 2 }
		} else {
			this.scale = { x: 5, y: 5, z: 5 }
		}
		this.id = i
	}

	draw() {
		if(((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) this.nowDist = lerp(this.nowDist, 250, 0.1)
		else this.nowDist = lerp(this.nowDist, this.dist, 0.1)

		graphics.push()
		if(abs(frameCount % 60 - this.id % 60) < 10) graphics.stroke(255)
		graphics.rotateX(this.r1.x + rotateCount)
		graphics.rotateY(this.r1.y + rotateCount)
		graphics.rotateZ(this.r1.z + rotateCount)
		graphics.translate(this.nowDist, 0, 0)
		graphics.rotateX(this.r2.x + rotateCount)
		graphics.rotateY(this.r2.y + rotateCount)
		graphics.rotateZ(this.r2.z + rotateCount)
		graphics.box(this.scale.x, this.scale.y, this.scale.z)
		graphics.pop()
	}
}

// === Tab: frag ===
//noprotect
const frag = `

precision mediump float;

uniform sampler2D mainTex;
uniform vec2 resolution;
uniform float time;
uniform vec2 mouse;

varying vec2 vTexCoord;

float random(float s) {
	return fract(sin(s * 123.45) * 48763.0);
}

float noise(vec2 p) {
	float a = random(floor(p.x) + floor(p.y) * 4.8763);
	float b = random((floor(p.x) + 1.0) + floor(p.y) * 4.8763);
	float c = random(floor(p.x) + (floor(p.y) + 1.0) * 4.8763);
	float d = random((floor(p.x) + 1.0) + (floor(p.y) + 1.0) * 4.8763);
	return mix(mix(a, b, smoothstep(0.0, 1.0, fract(p.x))), mix(c, d, smoothstep(0.0, 1.0, fract(p.x))), smoothstep(0.0, 1.0, fract(p.y)));
}

void main() {
	vec2 st = vTexCoord;
	vec4 color = vec4(0.0, 0.0, 0.0, 1.0);

	vec4 colorA = vec4(0, 0.8, 0.9, 1.0);
	vec4 colorB = vec4(0.8, 0.0, 1.0, 1.0);

	for(float i = 0.0; i < 1.0; i += 0.005) {
		vec2 p = mix(mouse, st, i);
		color += texture2D(mainTex, p) * i * 0.05 * colorA * noise(p * 8.0 + vec2(-time * 2.0, 0.0));
		color += texture2D(mainTex, p) * i * 0.05 * colorB * noise(p * 8.0 + vec2(100.0 + time, 0.0));
	}

	for(float i = 0.95; i < 1.0; i += 0.01) {
		vec2 p = mix(mouse, st, i);
		color += texture2D(mainTex, p) * i * 0.2 * colorA * noise(p * 8.0 + vec2(-time * 2.0, 0.0));
		color += texture2D(mainTex, p) * i * 0.2 * colorB * noise(p * 8.0 + vec2(100.0 + time, 0.0));
	}

	gl_FragColor = vec4(color.r, color.g, color.b, 1.0);
}

`

// === Tab: vert ===
const vert = `

attribute vec3 aPosition;
attribute vec2 aTexCoord;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;

varying vec2 vTexCoord;

void main() {
	vTexCoord = aTexCoord;
	vec4 pos = uProjectionMatrix * uModelViewMatrix * vec4(aPosition, 1.0);
	gl_Position = pos;
}

`

